UPDATE inventory_operation_effect SET effect_status = 'NOT_APPLIED', error_code = 'STALE_BEFORE_MUTATION', error_message = 'Repair 2026-10-27: the operation''s balance change was taken back by delta after an AFTER_BALANCE_WRITE stop; not applied', update_time = CONVERT_TZ(UTC_TIMESTAMP(3), '+00:00', '+08:00') WHERE tenant_id = '128671' AND operation_id = 'GD|2114978878563946498|2' AND effect_status = 'UNCERTAIN' AND IFNULL(movement_id, '') = '' AND applied_at IS NULL AND is_deleted = 0;

-- 3. gate -> REJECT|STALE_BEFORE_MUTATION|<same nonce>: expect 1 row(s) affected
UPDATE inventory_balance_lock SET owner_operation_id = 'REJECT|STALE_BEFORE_MUTATION|72657045ae0742aa86581204', update_time = CONVERT_TZ(UTC_TIMESTAMP(3), '+00:00', '+08:00') WHERE tenant_id = '128671' AND lock_key = 'GATE|GD|2114978878563946498|2' AND owner_operation_id = 'APPLY|72657045ae0742aa86581204' AND free_token = 0 AND is_deleted = 0;

-- 4. P3 step -> STARTED (same operation, attempt 2): expect 1 row(s) affected
UPDATE gd_publish_step SET step_status = 'STARTED', finished_at = NULL, result_ref = '', error_code = NULL, error_message = NULL, update_time = CONVERT_TZ(UTC_TIMESTAMP(3), '+00:00', '+08:00') WHERE tenant_id = '128671' AND id = 2114979012999778305 AND job_id = '2114978878563946498' AND step_name = 'P3_INVENTORY_APPLY' AND step_status = 'REQUIRES_REVIEW' AND inventory_operation_id = 'GD|2114978878563946498|2' AND attempt_count = 2 AND is_deleted = 0;

-- 5. job -> COMMITTING_GD, due now, no lease (LAST): expect 1 row(s) affected
UPDATE gd_async_job SET job_status = 'COMMITTING_GD', progress_percent = 70, progress_message = 'Publishing Goods Delivery', error_code = 'GD_INVENTORY_RETRYABLE_REJECTION', error_message = 'Stock is busy; retrying (STALE_BEFORE_MUTATION)', error_details = '{"inventory_operation_id":"GD|2114978878563946498|2","inventory_result_code":"STALE_BEFORE_MUTATION","review_reference":""}', next_attempt_at = NOW(3), lease_owner = NULL, lease_expires_at = NULL, finished_at = NULL, row_version = row_version + 1, update_time = CONVERT_TZ(UTC_TIMESTAMP(3), '+00:00', '+08:00') WHERE tenant_id = '128671' AND id = 2114978878563946498 AND job_status = 'REQUIRES_REVIEW' AND error_code = 'GD_INVENTORY_REQUIRES_REVIEW' AND IFNULL(lease_owner, '') = '' AND is_deleted = 0;

-- ===== PART 3: checks (read-only) =====
-- operation: REJECTED STALE_BEFORE_MUTATION, mutation_started_at NULL, summary all NOT_APPLIED
SELECT operation_status, result_code, mutation_started_at, review_reference, row_version, JSON_EXTRACT(effect_summary, '$.by_status') AS by_status FROM inventory_operation WHERE tenant_id = '128671' AND id = 2114979168885280770;

-- effects: 90 NOT_APPLIED
SELECT effect_status, COUNT(*) AS n FROM inventory_operation_effect WHERE tenant_id = '128671' AND operation_id = 'GD|2114978878563946498|2' AND is_deleted = 0 GROUP BY effect_status;

-- gate: REJECT|STALE_BEFORE_MUTATION|<nonce>
SELECT owner_operation_id, free_token FROM inventory_balance_lock WHERE tenant_id = '128671' AND lock_key = 'GATE|GD|2114978878563946498|2' AND is_deleted = 0;

-- P3 step: STARTED, operation |2, attempt 2
SELECT step_status, attempt_count, inventory_operation_id, finished_at FROM gd_publish_step WHERE tenant_id = '128671' AND id = 2114979012999778305;

-- job: COMMITTING_GD, due, no lease
SELECT job_status, error_code, row_version, attempt_count, lease_owner, (next_attempt_at <= NOW(3)) AS due FROM gd_async_job WHERE tenant_id = '128671' AND id = 2114978878563946498;

